using ProyectoFinal.Services; namespace ProyectoFinal.Views; public partial class InventoryPage : ContentPage { readonly ProductStore store = new(); public InventoryPage(){InitializeComponent();} protected override async void OnAppearing(){base.OnAppearing(); ProductList.ItemsSource=await store.GetAsync();} async void ConsumeClicked(object s, EventArgs e){if(s is Button b && b.CommandParameter is Guid id){await store.ConsumeAsync(id); ProductList.ItemsSource=await store.GetAsync();}} }
